INSERT INTO `careers` VALUES (1,'Software Engineer','Technology','Designs, develops and maintains software applications and systems.','Problem solving, programming, logical thinking, mathematics','2026-06-12 03:18:52','2026-06-12 03:18:52'),(2,'Cybersecurity Analyst','Technology','Protects computer systems and networks from digital attacks and threats.','Analytical thinking, networking, attention to detail','2026-06-12 03:18:53','2026-06-12 03:18:53'),(3,'Data Scientist','Technology','Analyses large datasets to extract insights and support decision-making.','Statistics, mathematics, programming, critical thinking','2026-06-12 03:18:53','2026-06-12 03:18:53'),(4,'Network Engineer','Technology','Designs and manages computer networks for organisations.','Networking, problem solving, technical knowledge','2026-06-12 03:18:53','2026-06-12 03:18:53'),(5,'Medical Doctor','Health','Diagnoses and treats illnesses and injuries, providing patient care.','Empathy, attention to detail, science knowledge, communication','2026-06-12 03:18:54','2026-06-12 03:18:54'),(6,'Nurse','Health','Provides care for patients in hospitals and health facilities.','Empathy, communication, attention to detail, resilience','2026-06-12 03:18:54','2026-06-12 03:18:54'),(7,'Pharmacist','Health','Prepares and dispenses medication and advises patients on drug use.','Chemistry knowledge, attention to detail, communication','2026-06-12 03:18:55','2026-06-12 03:18:55'),(8,'Medical Laboratory Scientist','Health','Performs laboratory tests to assist in the diagnosis of diseases.','Accuracy, science knowledge, analytical thinking','2026-06-12 03:18:55','2026-06-12 03:18:55'),(9,'Dentist','Health','Diagnoses and treats dental problems and oral health conditions.','Manual dexterity, attention to detail, patient care, science','2026-06-12 03:18:55','2026-06-12 03:18:55'),(10,'Civil Engineer','Engineering','Designs and supervises construction of infrastructure like roads, bridges and buildings.','Mathematics, physics, design, project management','2026-06-12 03:18:56','2026-06-12 03:18:56'),(11,'Electrical Engineer','Engineering','Designs and maintains electrical systems and equipment.','Mathematics, physics, problem solving, technical knowledge','2026-06-12 03:18:56','2026-06-12 03:18:56'),(12,'Mechanical Engineer','Engineering','Designs and manufactures mechanical systems and machines.','Mathematics, physics, design, creativity','2026-06-12 03:18:56','2026-06-12 03:18:56'),(13,'Agronomist','Agriculture','Studies crop production and soil management to improve farming yields.','Biology, chemistry, fieldwork, problem solving','2026-06-12 03:18:57','2026-06-12 03:18:57'),(14,'Environmental Scientist','Agriculture','Studies the environment and develops solutions to environmental problems.','Biology, chemistry, fieldwork, data analysis','2026-06-12 03:18:57','2026-06-12 03:18:57'),(15,'Veterinary Doctor','Agriculture','Diagnoses and treats diseases in animals.','Biology, empathy, science, problem solving','2026-06-12 03:18:58','2026-06-12 03:18:58'),(16,'Accountant','Business','Manages financial records, prepares reports and ensures tax compliance.','Mathematics, attention to detail, communication, analytical thinking','2026-06-12 03:18:58','2026-06-12 03:18:58'),(17,'Business Manager','Business','Plans and oversees operations within a business or organisation.','Leadership, communication, mathematics, decision-making','2026-06-12 03:18:59','2026-06-12 03:18:59'),(18,'Economist','Business','Analyses economic data to advise on policy and business decisions.','Mathematics, analytical thinking, research, communication','2026-06-12 03:18:59','2026-06-12 03:18:59'),(19,'Secondary School Teacher (Science)','Education','Teaches science subjects like Biology, Chemistry, Physics and Mathematics.','Communication, patience, subject knowledge, creativity','2026-06-12 03:19:00','2026-06-12 03:19:00'),(20,'ICT Teacher','Education','Teaches computer and information technology subjects in secondary schools.','Computer skills, communication, patience','2026-06-12 03:19:00','2026-06-12 03:19:00'),(21,'Journalist','Arts','Researches, writes and reports news for print, broadcast or digital media.','Writing, communication, curiosity, research','2026-06-12 03:19:01','2026-06-12 03:19:01'),(22,'Lawyer','Law','Provides legal advice and represents clients in legal proceedings.','Critical thinking, communication, research, ethics','2026-06-12 03:19:01','2026-06-12 03:19:01'),(23,'Social Worker','Arts','Helps individuals and communities address social, emotional and economic challenges.','Empathy, communication, problem solving, resilience','2026-06-12 03:19:01','2026-06-12 03:19:01');
