INSERT INTO `chatbot_messages` VALUES (1,1,'user','Which subjects should I pick?','2026-06-12 03:25:01','2026-06-12 03:25:01'),(2,1,'bot','Subject combinations are crucial for your career path. For Science careers like Engineering or Medicine, take Physics, Chemistry, and Biology/Maths. For Business careers, consider Accounting, Business Studies, and Economics. What career are you interested in?','2026-06-12 03:25:01','2026-06-12 03:25:01'),(3,1,'user','What universities can I apply to?','2026-06-12 03:25:59','2026-06-12 03:25:59'),(4,1,'bot','I\'m here to help with career guidance, subject selection, university applications, and more! What would you like to know? You can ask me about careers, subjects, universities, or the assessment process.','2026-06-12 03:25:59','2026-06-12 03:25:59'),(5,1,'user','How does the assessment work?','2026-06-12 03:26:17','2026-06-12 03:26:17'),(6,1,'bot','The career assessment helps match your interests and strengths with suitable careers. It takes about 15 minutes. Would you like to start the assessment now?','2026-06-12 03:26:17','2026-06-12 03:26:17'),(7,1,'user','yes','2026-06-12 03:26:32','2026-06-12 03:26:32'),(8,1,'bot','I\'m here to help with career guidance, subject selection, university applications, and more! What would you like to know? You can ask me about careers, subjects, universities, or the assessment process.','2026-06-12 03:26:32','2026-06-12 03:26:32'),(9,2,'user','What subjects should I take?','2026-06-13 11:05:10','2026-06-13 11:05:10'),(10,2,'bot','Subject combinations are crucial for your career path. For Science careers like Engineering or Medicine, take Physics, Chemistry, and Biology/Maths. For Business careers, consider Accounting, Business Studies, and Economics. What career are you interested in?','2026-06-13 11:05:10','2026-06-13 11:05:10'),(11,2,'user','What subjects should I take?','2026-06-13 11:05:12','2026-06-13 11:05:12'),(12,2,'bot','Subject combinations are crucial for your career path. For Science careers like Engineering or Medicine, take Physics, Chemistry, and Biology/Maths. For Business careers, consider Accounting, Business Studies, and Economics. What career are you interested in?','2026-06-13 11:05:12','2026-06-13 11:05:12'),(13,2,'user','hjjdhjdhhjds','2026-06-13 11:05:28','2026-06-13 11:05:28'),(14,2,'bot','I\'m here to help with career guidance, subject selection, university applications, and more! What would you like to know? You can ask me about careers, subjects, universities, or the assessment process.','2026-06-13 11:05:28','2026-06-13 11:05:28');
