DROP TABLE IF EXISTS `recommendations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recommendations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint unsigned NOT NULL,
  `attempt_id` bigint unsigned DEFAULT NULL,
  `type` enum('career','subject_combination','university_program') COLLATE utf8mb4_unicode_ci NOT NULL,
  `recommended_id` bigint unsigned NOT NULL,
  `recommended_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `confidence_score` decimal(5,2) DEFAULT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci,
  `status` enum('pending','viewed','accepted','dismissed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `recommendations_student_id_foreign` (`student_id`),
  KEY `recommendations_attempt_id_foreign` (`attempt_id`),
  KEY `recommendations_recommended_id_recommended_type_index` (`recommended_id`,`recommended_type`),
  CONSTRAINT `recommendations_attempt_id_foreign` FOREIGN KEY (`attempt_id`) REFERENCES `assessment_attempts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `recommendations_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=885 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

